import { createI18n } from 'vue-i18n'
import ru from './ru'
import uk from './uk'
import en from './en'

// ── Миграция локали ───────────────────────────────────────
// При смене дефолтного языка увеличь LOCALE_VERSION —
// тогда все пользователи один раз сбросятся на новый дефолт,
// после чего их ручной выбор снова сохраняется.
const LOCALE_VERSION  = '2'
const DEFAULT_LOCALE  = 'uk'

const savedVersion = localStorage.getItem('locale_version')
let savedLocale    = localStorage.getItem('locale')

if (savedVersion !== LOCALE_VERSION) {
  // Первый запуск с новой версией — применяем новый дефолт
  savedLocale = DEFAULT_LOCALE
  localStorage.setItem('locale', DEFAULT_LOCALE)
  localStorage.setItem('locale_version', LOCALE_VERSION)
}

const i18n = createI18n({
  legacy:         false,
  locale:         savedLocale || DEFAULT_LOCALE,
  fallbackLocale: 'uk',
  messages: { ru, uk, en },
})

export default i18n
